package com.hbm.machine.excavator;
import api.hbm.redstoneoverradio.*;import api.hbm.conveyor.*;import com.hbm.api.machine.*;import com.hbm.block.ore.*;import com.hbm.conveyor.MovingItem;import com.hbm.energy.*;import com.hbm.fluid.*;import com.hbm.fluid.network.*;import com.hbm.item.battery.*;import com.hbm.item.bedrockresource.RawBedrockOreItem;import com.hbm.machine.electricfurnace.FurnaceUpgradeItem;import com.hbm.machine.crystallizer.EffectUpgradeItem;import com.hbm.multiblock.*;import java.util.*;import net.minecraft.core.*;import net.minecraft.core.registries.Registries;import net.minecraft.nbt.CompoundTag;import net.minecraft.network.chat.Component;import net.minecraft.network.protocol.game.ClientboundBlockEntityDataPacket;import net.minecraft.server.level.ServerLevel;import net.minecraft.world.*;import net.minecraft.world.entity.item.ItemEntity;import net.minecraft.world.entity.player.*;import net.minecraft.world.inventory.*;import net.minecraft.world.item.*;import net.minecraft.world.item.enchantment.Enchantments;import net.minecraft.world.level.*;import net.minecraft.world.level.block.*;import net.minecraft.world.level.block.entity.BlockEntity;import net.minecraft.world.level.block.state.BlockState;import net.minecraft.world.phys.AABB;
/** Actual X5846 excavator. All drill, ore-recursion, walling, acid, buffering and conveyor branches execute here. */
public final class ExcavatorBlockEntity extends BlockEntity implements WorldlyContainer,MenuProvider,NamedMultiblock,EnergyReceiver,SidedEnergyConnector,StandardFluidReceiver,MachineView,IFluidCopiable,IRORValueProvider,IRORInteractive, com.hbm.multiblock.MuffledMachine {
 public static final long MAX_POWER=1000000;private final ItemStack[] slots=new ItemStack[14];public final FluidTank tank=new FluidTank(HbmFluids.NONE,16000);public long power,consumption=10000;public boolean operational,enableDrill,enableCrusher,enableWalling,enableVeinMiner,enableSilkTouch,bedrockDrilling;private int ticksWorked;public int targetDepth,chuteTimer;public double speed=1;public float drillRotation,prevDrillRotation,drillExtension,prevDrillExtension,crusherRotation,prevCrusherRotation;private Component customName;public boolean muffled,tilted;private final Map<BlockPos,PowerNode> nodes=new LinkedHashMap<>();private FluidPorts fluids;
 public ExcavatorBlockEntity(BlockPos pos,BlockState state){super(ExcavatorContent.ENTITY.get(),pos,state);Arrays.fill(slots,ItemStack.EMPTY);}
 @Override public boolean isValidBlockState(BlockState state){return super.isValidBlockState(state)&&DummyableBlock.isCore(state);}@Override public Component getDisplayName(){return customName==null?Component.translatable("container.machineExcavator"):customName;}@Override public void setCustomName(Component name){customName=name;setChanged();}@Override public AbstractContainerMenu createMenu(int id,Inventory inv,Player player){return new ExcavatorMenu(id,inv,this,worldPosition);}
 public record Port(BlockPos pos,Direction side){}public static Port[] ports(BlockPos p,Direction d){var r=d.getClockWise();return new Port[]{new Port(p.above().relative(d,3).relative(r),d),new Port(p.above().relative(d,3).relative(r,-1),d),new Port(p.above().relative(r,3),r),new Port(p.above().relative(r,-3),r.getOpposite())};}
 public static void tick(Level level,BlockPos pos,BlockState state,ExcavatorBlockEntity m){m.upgrades();if(level instanceof ServerLevel server)m.serverTick(server);else m.clientTick();}
 private int speedTier,powerTier,effectTier;private void upgrades(){speedTier=0;powerTier=0;effectTier=0;for(int i=2;i<=3;i++){if(slots[i].getItem() instanceof FurnaceUpgradeItem u){if(u.type()==FurnaceUpgradeItem.Type.SPEED)speedTier+=u.tier();else powerTier+=u.tier();}else if(slots[i].getItem() instanceof EffectUpgradeItem u)effectTier+=u.tier();}speedTier=Math.min(3,speedTier);powerTier=Math.min(3,powerTier);effectTier=Math.min(3,effectTier);consumption=10000L*(1+speedTier)/(1+powerTier);}
 private void serverTick(ServerLevel server){updatePorts(server);tank.setType(1,slots);if(server.getGameTime()%20==0)tryEjectBuffer();if(chuteTimer>0)chuteTimer--;charge();operational=false;var drill=drill();if(enableDrill&&drill!=null&&power>=consumption){operational=true;power-=consumption;speed=drill.speed(slots[4])*(1+speedTier/2D);int maxDepth=worldPosition.getY()-4-server.getMinBuildHeight();if((bedrockDrilling||targetDepth<=maxDepth)&&tryDrill(1+effectTier*2)){targetDepth++;if(targetDepth>maxDepth)enableDrill=false;}}else targetDepth=0;setChanged();var packet=getUpdatePacket();try(var dispatchScope=com.hbm.network.dispatch.PacketDispatch.beginGroup(server.getServer(),packet)){for(var player:server.players())if(player.distanceToSqr(worldPosition.getX(),worldPosition.getY(),worldPosition.getZ())<22500)player.connection.send(packet);dispatchScope.commit();}}
 private void charge(){if(power<0){power=0;return;}if(power>MAX_POWER){power=MAX_POWER;return;}if(slots[0].getItem() instanceof CreativeBatteryItem){power=MAX_POWER;return;}if(slots[0].getItem() instanceof HbmBattery b){long amount=Math.min(Math.min(MAX_POWER-power,b.getDischargeRate(slots[0])),b.getCharge(slots[0]));power+=amount;b.dischargeBattery(slots[0],amount);}}
 private void clientTick(){prevDrillExtension=drillExtension;if(drillExtension!=targetDepth){float diff=Math.abs(drillExtension-targetDepth),step=Math.max(.15F,diff/10F);if(diff<=step)drillExtension=targetDepth;else drillExtension-=Math.signum(drillExtension-targetDepth)*step;}prevDrillRotation=drillRotation;prevCrusherRotation=crusherRotation;if(operational){drillRotation+=15;if(enableCrusher)crusherRotation+=15;}if(drillRotation>=360){drillRotation-=360;prevDrillRotation-=360;}if(crusherRotation>=360){crusherRotation-=360;prevCrusherRotation-=360;}}
 public DrillbitItem drill(){return slots[4].getItem() instanceof DrillbitItem drill?drill:null;}public boolean canVeinMine(){return enableVeinMiner&&drill()!=null&&drill().vein(slots[4]);}public boolean canSilkTouch(){return enableSilkTouch&&drill()!=null&&drill().silk(slots[4]);}public int fortune(){return drill()==null?0:drill().fortune(slots[4]);}private int drillY(){return worldPosition.getY()-targetDepth-4;}
 private boolean tryDrill(int radius){int y=drillY();if(targetDepth==0||y==level.getMinBuildHeight())radius=1;for(int ring=1;ring<=radius;ring++){boolean ignoreAll=true;float hardness=0;BlockPos bedrock=null;bedrockDrilling=false;for(int x=worldPosition.getX()-ring;x<=worldPosition.getX()+ring;x++)for(int z=worldPosition.getZ()-ring;z<=worldPosition.getZ()+ring;z++)if(edge(x,z,ring)){var p=new BlockPos(x,y,z);var state=level.getBlockState(p);if(state.getBlock() instanceof BedrockOreBlock){hardness=6000;bedrock=p;bedrockDrilling=true;enableCrusher=false;ignoreAll=false;break;}if(state.getBlock() instanceof com.hbm.worldgen.depthdeposit.DepthRockBlock)enableDrill=false;if(ignore(state,p))continue;ignoreAll=false;hardness+=state.getDestroySpeed(level,p);}if(!ignoreAll){ticksWorked++;int required=(int)Math.ceil(hardness/speed);if(ticksWorked>=required){if(bedrock==null){breakBlocks(ring);buildWall(ring+1,ring==radius&&enableWalling);if(ring==radius)mineOuterOres(ring+1);tryCollect(radius+1);}else collectBedrock(bedrock);ticksWorked=0;}return false;}else tryCollect(radius+1);}buildWall(radius+1,enableWalling);ticksWorked=0;return true;}
 private boolean edge(int x,int z,int ring){return ring==1||x==worldPosition.getX()-ring||x==worldPosition.getX()+ring||z==worldPosition.getZ()-ring||z==worldPosition.getZ()+ring;}
 private void collectBedrock(BlockPos p){if(!(level.getBlockEntity(p) instanceof BedrockOreEntity ore)||ore.resource.isEmpty()||drill()==null||ore.tier>drill().tier(slots[4]))return;if(ore.acidRequirement!=null){if(ore.acidRequirement.type!=tank.getTankType()||ore.acidRequirement.fill>tank.getFill())return;tank.setFill(tank.getFill()-ore.acidRequirement.fill);}var stack=ore.resource.copy();if(stack.getItem() instanceof RawBedrockOreItem)RawBedrockOreItem.setOreAmount(stack,p.getX(),p.getZ(),1D+drill().fortune(slots[4])*.1D);var list=new ArrayList<ItemStack>();list.add(stack);supply(list);if(stack.isEmpty())return;buffer(stack,null);}
 private void breakBlocks(int ring){int y=drillY();for(int x=worldPosition.getX()-ring;x<=worldPosition.getX()+ring;x++)for(int z=worldPosition.getZ()-ring;z<=worldPosition.getZ()+ring;z++)if(edge(x,z,ring)){var p=new BlockPos(x,y,z);if(!ignore(level.getBlockState(p),p))mine(p);}}
 private boolean isOre(BlockState state){return state.getBlock().asItem()!=Items.AIR&&com.hbm.registry.HbmItemTags.tags(new ItemStack(state.getBlock())).stream().anyMatch(com.hbm.fuel.HbmFuels::isOreTag);}
 private final Set<BlockPos> recursionBrake=new HashSet<>();private int minX,minY,minZ,maxX,maxY,maxZ;
 private void mine(BlockPos p){var state=level.getBlockState(p);if(canVeinMine()&&isOre(state)){minX=maxX=p.getX();minY=maxY=p.getY();minZ=maxZ=p.getZ();breakRecursively(p,10);recursionBrake.clear();for(var item:level.getEntitiesOfClass(ItemEntity.class,new AABB(minX,minY,minZ,maxX+1,maxY+1,maxZ+1)))item.setPos(p.getX()+.5,p.getY()+.5,p.getZ()+.5);return;}breakSingleBlock(p,state);}
 private void breakRecursively(BlockPos p,int depth){if(depth<0||!recursionBrake.add(p))return;var state=level.getBlockState(p);for(var side:Direction.values())if(level.getBlockState(p.relative(side)).getBlock()==state.getBlock())breakRecursively(p.relative(side),depth-1);breakSingleBlock(p,state);minX=Math.min(minX,p.getX());minY=Math.min(minY,p.getY());minZ=Math.min(minZ,p.getZ());maxX=Math.max(maxX,p.getX());maxY=Math.max(maxY,p.getY());maxZ=Math.max(maxZ,p.getZ());if(enableWalling)level.setBlockAndUpdate(p,ExcavatorContent.BARRICADE.get().defaultBlockState());}
 private void breakSingleBlock(BlockPos p,BlockState state){var tool=new ItemStack(Items.DIAMOND_PICKAXE);if(fortune()>0)tool.enchant(level.registryAccess().lookupOrThrow(Registries.ENCHANTMENT).getOrThrow(Enchantments.FORTUNE),fortune());var items=new ArrayList<>(Block.getDrops(state,(ServerLevel)level,p,level.getBlockEntity(p),null,tool));if(canSilkTouch()&&state.getBlock().asItem()!=Items.AIR){var clone=state.getBlock().getCloneItemStack(level,p,state);if(!clone.isEmpty()){items.clear();items.add(clone.copy());}}if(enableCrusher){var crushedItems=new ArrayList<ItemStack>();for(var item:items){var crushed=com.hbm.machine.shredder.ShredderRecipes.result(level,item);var id=net.minecraft.core.registries.BuiltInRegistries.ITEM.getKey(crushed.getItem());if(id.equals(ExcavatorContent.id("scrap"))||id.equals(ExcavatorContent.id("dust")))crushedItems.add(item);else{crushed.setCount(crushed.getCount()*item.getCount());crushedItems.add(crushed);}}items=crushedItems;}if(state.is(ExcavatorContent.BARRICADE.get()))items.clear();for(var item:items)level.addFreshEntity(new ItemEntity(level,p.getX()+.5,p.getY()+.5,p.getZ()+.5,item));level.destroyBlock(p,false);}
 private boolean ignore(BlockState state,BlockPos p){return state.isAir()||state.getBlock() instanceof com.hbm.block.gas.GasBlock||state.getDestroySpeed(level,p)<0||state.liquid()||state.is(Blocks.BEDROCK);}
 private void buildWall(int ring,boolean everything){int y=drillY();for(int x=worldPosition.getX()-ring;x<=worldPosition.getX()+ring;x++)for(int z=worldPosition.getZ()-ring;z<=worldPosition.getZ()+ring;z++){var p=new BlockPos(x,y,z);var state=level.getBlockState(p);boolean liquid=state.liquid();if(x==worldPosition.getX()-ring||x==worldPosition.getX()+ring||z==worldPosition.getZ()-ring||z==worldPosition.getZ()+ring){if(state.canBeReplaced()&&(everything||liquid))level.setBlockAndUpdate(p,ExcavatorContent.BARRICADE.get().defaultBlockState());}else if(liquid)level.removeBlock(p,false);}}
 private void mineOuterOres(int ring){int y=drillY();for(int x=worldPosition.getX()-ring;x<=worldPosition.getX()+ring;x++)for(int z=worldPosition.getZ()-ring;z<=worldPosition.getZ()+ring;z++)if(edge(x,z,ring)){var p=new BlockPos(x,y,z);var state=level.getBlockState(p);if(!ignore(state,p)&&isOre(state))mine(p);}}
 private BlockPos output(){return worldPosition.relative(DummyableBlock.facing(getBlockState()),4).below(3);}
 private void supply(List<ItemStack> items){var p=output();var side=DummyableBlock.facing(getBlockState()).getOpposite();if(level.getBlockEntity(p) instanceof Container container)for(var item:items){if(item.isEmpty())continue;insert(container,item,side);chuteTimer=40;}if(level.getBlockState(p).getBlock() instanceof IConveyorBelt belt)for(var item:items){if(item.isEmpty())continue;var base=new net.minecraft.world.phys.Vec3(p.getX()+level.random.nextDouble(),p.getY()+.5,p.getZ()+level.random.nextDouble());var snap=belt.getClosestSnappingPosition(level,p.getX(),p.getY(),p.getZ(),base);var moving=new MovingItem(level);moving.setPos(base.x,snap.y,base.z);moving.setItemStack(item.copy());level.addFreshEntity(moving);item.setCount(0);chuteTimer=40;}}
 /** Original CraneInserter: merge every permitted existing stack before taking permitted empty slots. */
 private void insert(Container inv,ItemStack stack,Direction side){int[] access=inv instanceof net.minecraft.world.level.block.entity.FurnaceBlockEntity?new int[]{1,0}:inv instanceof WorldlyContainer sided?sided.getSlotsForFace(side):java.util.stream.IntStream.range(0,inv.getContainerSize()).toArray();for(int pass=0;pass<2;pass++)for(int index:access){if(stack.isEmpty())return;var present=inv.getItem(index);if(!inv.canPlaceItem(index,stack)||inv instanceof WorldlyContainer sided&&!sided.canPlaceItemThroughFace(index,stack,side))continue;if(pass==0&&!present.isEmpty()&&ItemStack.isSameItemSameComponents(present,stack)){int count=Math.min(stack.getCount(),Math.min(present.getMaxStackSize(),inv.getMaxStackSize())-present.getCount());if(count>0){present.grow(count);stack.shrink(count);inv.setChanged();}}else if(pass==1&&present.isEmpty()){int count=Math.min(stack.getCount(),inv.getMaxStackSize());inv.setItem(index,stack.copyWithCount(count));stack.shrink(count);inv.setChanged();}}}
 private void tryEjectBuffer(){var items=new ArrayList<ItemStack>();for(int i=5;i<14;i++)if(!slots[i].isEmpty())items.add(slots[i].copy());supply(items);items.removeIf(ItemStack::isEmpty);for(int i=5;i<14;i++)slots[i]=items.size()>i-5?items.get(i-5).copy():ItemStack.EMPTY;}
 private void tryCollect(int radius){int y=drillY();var items=level.getEntitiesOfClass(ItemEntity.class,new AABB(worldPosition.getX()-radius,y-1,worldPosition.getZ()-radius,worldPosition.getX()+radius+1,y+2,worldPosition.getZ()+radius+1));var stacks=new ArrayList<ItemStack>();for(var item:items)if(!item.isRemoved())stacks.add(item.getItem());supply(stacks);items.removeIf(item->item.isRemoved()||item.getItem().isEmpty());for(var item:items)if(!item.isRemoved())buffer(item.getItem(),item);}
 private void buffer(ItemStack stack,ItemEntity entity){for(int i=5;i<14;i++)if(!slots[i].isEmpty()&&ItemStack.isSameItemSameComponents(slots[i],stack)&&slots[i].getCount()<slots[i].getMaxStackSize()){int amount=Math.min(slots[i].getMaxStackSize()-slots[i].getCount(),stack.getCount());slots[i].grow(amount);stack.shrink(amount);chuteTimer=40;if(stack.isEmpty()){if(entity!=null){entity.discard();entity.setPickUpDelay(60);}return;}}for(int i=5;i<14;i++)if(slots[i].isEmpty()){slots[i]=stack.copy();chuteTimer=40;if(entity!=null){entity.discard();entity.setPickUpDelay(60);}return;}}
 public void toggle(String key){switch(key){case "drill"->enableDrill=!enableDrill;case "crusher"->enableCrusher=!enableCrusher;case "walling"->enableWalling=!enableWalling;case "veinminer"->enableVeinMiner=!enableVeinMiner;case "silktouch"->enableSilkTouch=!enableSilkTouch;default->{return;}}setChanged();}
 @Override public String[] getFunctionInfo(){return new String[]{PREFIX_VALUE+"power",PREFIX_VALUE+"fluid",PREFIX_VALUE+"state",PREFIX_FUNCTION+"setstate"+NAME_SEPARATOR+"state"};}@Override public String provideRORValue(String name){return switch(name){case PREFIX_VALUE+"power"->Long.toString(power);case PREFIX_VALUE+"fluid"->Integer.toString(tank.getFill());case PREFIX_VALUE+"state"->operational?"1":"0";default->null;};}@Override public String runRORFunction(String name,String[] params){if((PREFIX_FUNCTION+"setstate").equals(name)&&params.length==1){enableDrill=params[0].equals("1");setChanged();}return null;}
 private void updatePorts(ServerLevel server){if(nodes.isEmpty()||nodes.values().stream().anyMatch(PowerNode::isExpired)){disconnect();var ports=ports(worldPosition,DummyableBlock.facing(getBlockState()));var edges=new ArrayList<NodeConnection>();for(var port:ports){var edge=new NodeConnection(port.pos().relative(port.side()),port.side());var node=new PowerNode(port.pos()).setConnections(edge);HbmEnergy.nodespace(server).createNode(node);nodes.put(port.pos(),node);edges.add(edge);}fluids=new FluidPorts(nodes.keySet().toArray(BlockPos[]::new),edges.toArray(NodeConnection[]::new));}fluids.update(server,this);for(var node:nodes.values())if(node.hasValidNet())node.addReceiver(this);}
 private void disconnect(){if(level instanceof ServerLevel server){for(var node:nodes.values())HbmEnergy.nodespace(server).destroyNode(node);if(fluids!=null)fluids.remove(server);}nodes.clear();fluids=null;}@Override public void setRemoved(){disconnect();super.setRemoved();}@Override public void onChunkUnloaded(){disconnect();super.onChunkUnloaded();}@Override public boolean isLoaded(){return !isRemoved()&&level!=null&&level.hasChunkAt(worldPosition);}@Override public boolean canConnect(Direction side){return side!=null;}@Override public boolean canConnect(HbmFluidType type,Direction side){return side!=null;}@Override public long getPower(){return power;}@Override public long getMaxPower(){return MAX_POWER;}@Override public void setPower(long value){power=value;setChanged();}@Override public FluidTank[] getAllTanks(){return new FluidTank[]{tank};}@Override public FluidTank[] getReceivingTanks(){return getAllTanks();}@Override public long transferFluid(HbmFluidType type,int pressure,long amount){long rejected=StandardFluidReceiver.super.transferFluid(type,pressure,amount);if(amount!=rejected)setChanged();return rejected;}@Override public FluidTank getTankToPaste(){return tank;}@Override public long energyStored(){return power;}@Override public long energyCapacity(){return MAX_POWER;}@Override public List<TankView> tanks(){return List.of(new TankView(tank.getTankType(),tank.getFill(),tank.getMaxFill()));}
 private void writeState(CompoundTag tag){tag.putBoolean("d",enableDrill);tag.putBoolean("c",enableCrusher);tag.putBoolean("w",enableWalling);tag.putBoolean("v",enableVeinMiner);tag.putBoolean("s",enableSilkTouch);tag.putInt("t",targetDepth);tag.putLong("p",power);tag.putBoolean("operational",operational);tag.putInt("chuteTimer",chuteTimer);tag.putBoolean("muffled",muffled);tag.putBoolean("tilted",tilted);tank.writeToNBT(tag,"tank");}
 private void readState(CompoundTag tag){enableDrill=tag.getBoolean("d");enableCrusher=tag.getBoolean("c");enableWalling=tag.getBoolean("w");enableVeinMiner=tag.getBoolean("v");enableSilkTouch=tag.getBoolean("s");targetDepth=tag.getInt("t");power=tag.getLong("p");operational=tag.getBoolean("operational");chuteTimer=tag.getInt("chuteTimer");muffled=tag.getBoolean("muffled");tilted=tag.getBoolean("tilted");tank.readFromNBT(tag,"tank");}
 @Override protected void saveAdditional(CompoundTag tag,HolderLookup.Provider lookup){super.saveAdditional(tag,lookup);var items=NonNullList.withSize(14,ItemStack.EMPTY);for(int i=0;i<14;i++)items.set(i,slots[i]);ContainerHelper.saveAllItems(tag,items,lookup);writeState(tag);tag.remove("operational");tag.remove("chuteTimer");if(customName!=null)tag.putString("CustomName",Component.Serializer.toJson(customName,lookup));}@Override protected void loadAdditional(CompoundTag tag,HolderLookup.Provider lookup){super.loadAdditional(tag,lookup);var items=NonNullList.withSize(14,ItemStack.EMPTY);ContainerHelper.loadAllItems(tag,items,lookup);for(int i=0;i<14;i++)slots[i]=items.get(i);readState(tag);if(tag.contains("CustomName"))customName=Component.Serializer.fromJson(tag.getString("CustomName"),lookup);}
 @Override public CompoundTag getUpdateTag(HolderLookup.Provider lookup){var tag=new CompoundTag();writeState(tag);var upgrades=NonNullList.withSize(14,ItemStack.EMPTY);upgrades.set(2,slots[2]);upgrades.set(3,slots[3]);upgrades.set(4,slots[4]);ContainerHelper.saveAllItems(tag,upgrades,lookup);return tag;}@Override public void handleUpdateTag(CompoundTag tag,HolderLookup.Provider lookup){readState(tag);var upgrades=NonNullList.withSize(14,ItemStack.EMPTY);ContainerHelper.loadAllItems(tag,upgrades,lookup);for(int i=2;i<=4;i++)slots[i]=upgrades.get(i);}@Override public ClientboundBlockEntityDataPacket getUpdatePacket(){return ClientboundBlockEntityDataPacket.create(this);}@Override public void onDataPacket(net.minecraft.network.Connection connection,ClientboundBlockEntityDataPacket packet,HolderLookup.Provider lookup){handleUpdateTag(packet.getTag(),lookup);}
 @Override public int getContainerSize(){return 14;}@Override public boolean isEmpty(){return Arrays.stream(slots).allMatch(ItemStack::isEmpty);}@Override public ItemStack getItem(int slot){return slots[slot];}@Override public ItemStack removeItem(int slot,int count){var stack=slots[slot].split(count);if(!stack.isEmpty())setChanged();return stack;}@Override public ItemStack removeItemNoUpdate(int slot){var stack=slots[slot];slots[slot]=ItemStack.EMPTY;return stack;}@Override public void setItem(int slot,ItemStack stack){slots[slot]=stack;if(stack.getCount()>64)stack.setCount(64);setChanged();}@Override public void clearContent(){Arrays.fill(slots,ItemStack.EMPTY);setChanged();}@Override public boolean stillValid(Player player){return level!=null&&level.getBlockEntity(worldPosition)==this&&player.distanceToSqr(worldPosition.getX()+.5,worldPosition.getY()+.5,worldPosition.getZ()+.5)<=144;}@Override public boolean canPlaceItem(int slot,ItemStack stack){return false;}@Override public int[] getSlotsForFace(Direction side){return new int[0];}@Override public boolean canPlaceItemThroughFace(int slot,ItemStack stack,Direction side){return false;}@Override public boolean canTakeItemThroughFace(int slot,ItemStack stack,Direction side){return false;}

 @Override public boolean isMuffled(){return muffled;}
 @Override public void setMuffled(boolean value){muffled=value;}
}
